#!/usr/bin/env python3
"""Каталог v5: чекап из шести карточек, контексты работы, первый день и обучение. Запуск после content_v4: python3 tools/content_v5.py"""
import json, re, os
SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "content.js")
src = open(SRC, encoding="utf-8").read()
m = re.search(r"window\.KARMA_CONTENT\s*=\s*", src); start = m.end()
depth = 0; i = start
while True:
    ch = src[i]
    if ch == "{": depth += 1
    elif ch == "}":
        depth -= 1
        if depth == 0: break
    i += 1
C = json.loads(src[start:i + 1]); X = C["extra"]
C["contentVersion"] = "2026-10-15-v5"

